 if(L.must)L.must.forEach(r=>{if(!av2(L,r)||out.some(x=>(r!=='wbk'&&x.res===r)||x.kind===r))return;let k=out.findIndex(x=>(r==='vgames'?['act']:['recog','recall','say']).includes(x.pur)&&!L.must.includes(x.res)&&!L.must.includes(x.kind)&&x.res!=='scene');if(k<0&&r==='wbk')k=out.map(x=>x.res).lastIndexOf(out.map(x=>x.res).filter(q=>['doors','wheel','mime','show','tap','shadow','memory','balloons'].includes(q)).pop());if(k<0)return;const o=out[k];out[k]=stageFor(L,own,{kind:r,res:r==='vgames'?'clips':r,pur:o.pur},o.phase,o.min,o.frame,rnd,ch)});
 orderFix(out);
 for(let i=1;i<out.length;i++){if(out[i].res===out[i-1].res&&out[i].res!=='clips'&&out[i].res!=='wbk'){out.splice(i,1);i--}}
 // keep 2D and 3D apart: 3D "solids" comes after all the 2D work, just before the goodbye stages
 {const si=out.findIndex(x=>x.res==='solids');if(si>=0&&L.pics2d){let e=out.length;while(e>0&&(out[e-1].kind==='timetogo'||out[e-1].res==='bye'))e--;if(si<e-1){const s=out.splice(si,1)[0];const prev=out[e-2];s.phase=prev.phase;s.frame=prev.frame;out.splice(e-1,0,s)}}}
